addition="\nfor(const method of ['next','return','throw'] as const)test('captured observer cannot recursively enter its protected cursor '+method,()=>{\n let cursor:SolidSteps<SolidMesh>,attempted=false,refusal:unknown;const session=create({tick:()=>{if(!attempted){attempted=true;try{if(method==='next')cursor.next();else if(method==='return')cursor.return(undefined as unknown as SolidMesh);else cursor.throw(undefined);}catch(error){refusal=error;}}}});cursor=session.booleanSteps('union',box(cases.cases[0]!.host),box(cases.cases[0]!.host));let caught=false;try{drain(cursor);}catch(error){caught=true;expect(error).toBe(refusal);expect(String(error)).toContain('boolean-session-reentrant');}expect(caught).toBe(true);session.close();\n});\ntest('unentered stale returns cannot release another cursor ownership',()=>{const session=create(),first=session.booleanSteps('union',box(cases.cases[0]!.host),box(cases.cases[0]!.host)),unused=session.booleanSteps('intersection',box(cases.cases[0]!.host),box(cases.cases[0]!.host));expect(first.next().done).toBe(false);const before=session.work;expect(unused.return(undefined as unknown as SolidMesh).done).toBe(true);expect(unused.next().done).toBe(true);expect(session.work).toBe(before);expect(()=>session.checkpoint()).toThrow('boolean-session-active');expect(()=>first.next()).toThrow('boolean-session-active');first.return(undefined as unknown as SolidMesh);session.close();});\ntest('protected cursors delegate through their own iterator and hide native generator receivers',()=>{const session=create(),cursor=session.booleanSteps('union',box(cases.cases[0]!.host),box(cases.cases[0]!.host));expect(cursor[Symbol.iterator]()).toBe(cursor);const prototype=Object.getPrototypeOf(cursor) as SolidSteps<SolidMesh>;for(const method of ['next','return','throw'] as const)expect(()=>Reflect.apply(prototype[method],cursor,[])).toThrow(TypeError);expect(session.work).toBe(0);function* outer():SolidSteps<SolidMesh>{return yield* cursor;}expect(volume(drain(outer()))).toBeCloseTo(64,8);session.close();});\ntest('checkpoint never accepts a work refund parameter',()=>{const session=create({maxWork:3});Reflect.apply(session.checkpoint,session,[-100]);expect(session.work).toBe(1);session.checkpoint();session.checkpoint();expect(session.work).toBe(3);expect(()=>session.checkpoint()).toThrow('boolean-work-limit');expect(session.work).toBe(3);session.close();});\ntest('halfspace and subsequent finite operation share the same session work',()=>{const host=box(cases.cases[0]!.host),plane:SolidPlane={origin:[0,0,2],normal:[0,0,1]},right=box([[2,0,0],[6,4,4]]),run=(session:Session)=>{session.checkpoint();const half=drain(session.halfSpaceSteps(host,plane));expect(volume(half)).toBeCloseTo(32,8);return drain(session.booleanSteps('difference',half,right));},session=create(),result=run(session),work=session.work;expect(volume(result)).toBeCloseTo(16,8);expect(()=>run(create({maxWork:work-1}))).toThrow('boolean-work-limit');const exact=create({maxWork:work});expect(run(exact)).toEqual(result);expect(exact.work).toBe(work);session.close();exact.close();});\nfor(const original of [undefined,null,false,17,{identity:'original'},Symbol('original')])test('injected cursor failure preserves the first original value '+String(original),()=>{const session=create(),cursor=session.booleanSteps('union',box(cases.cases[0]!.host),box(cases.cases[0]!.host));expect(cursor.next().done).toBe(false);let caught=false;try{cursor.throw(original);}catch(error){caught=true;expect(error).toBe(original);}expect(caught).toBe(true);let resumed=false;try{session.checkpoint();}catch(error){resumed=true;expect(error).toBe(original);}expect(resumed).toBe(true);cursor.return(undefined as unknown as SolidMesh);session.close();});\n"
